/// The same explicit fixture Root validates the distribution before returning
/// either its activated writer authority or the full host-owned trust clone.
/// A parent can call this with its own preselected objective/time before a
/// child reports material. Child metadata never selects a new trust state.
pub(super) fn original_fixture_trust_at(
    objective: Digest32,
    at: u64,
) -> anyhow::Result<(ActivatedLearningTrustV1, Credentials, LearningEvidenceTrustV1)> {
    let credentials = Credentials {
        generator: signer(
            "positive-generator",
            LearningEvidenceRoleV1::Generator,
            41,
            at,
        ),
        evaluator: signer(
            "positive-evaluator",
            LearningEvidenceRoleV1::Evaluator,
            42,
            at,
        ),
        observer: signer("positive-outcome", LearningEvidenceRoleV1::Observer, 43, at),
        experience: signer(
            "positive-experience",
            LearningEvidenceRoleV1::Observer,
            44,
            at,
        ),
        dataset: signer("positive-dataset", LearningEvidenceRoleV1::Observer, 45, at),
        selector: signer(
            "positive-selector",
            LearningEvidenceRoleV1::Selector,
            46,
            at,
        ),
        unlearning: signer(
            "positive-unlearning",
            LearningEvidenceRoleV1::UnlearningAuthority,
            48,
            at,
        ),
    };
    let mut distribution = SignedLearningTrustDistributionV1 {
        distribution: LearningTrustDistributionV1 {
            distribution_id: id("explicit-positive-trust-distribution"),
            generation: 1,
            effective_at: at - 40,
            trust: LearningEvidenceTrustV1 {
                scope_digest: d("explicit-positive-original-trust"),
                objective_digest: objective,
                authority_epoch: 7,
                signers: vec![
                    credentials.generator.clone(),
                    credentials.evaluator.clone(),
                    credentials.observer.clone(),
                    credentials.experience.clone(),
                    credentials.dataset.clone(),
                    credentials.selector.clone(),
                    credentials.unlearning.clone(),
                ],
            },
        },
        root_id: id("explicit-positive-root"),
        issued_at: at - 45,
        expires_at: at + 3_000,
        signature: [0; 64],
    };
    let root_key = SigningKey::from_bytes(&[99; 32]);
    distribution.signature = root_key.sign(&distribution.signing_bytes()?).to_bytes();
    let original_trust = distribution.distribution.trust.clone();
    let trust = activate_learning_trust(
        &LearningTrustRootV1 {
            root_id: distribution.root_id.clone(),
            scope_digest: d("explicit-positive-original-trust"),
            verifying_key: root_key.verifying_key().to_bytes(),
            valid_from: at - 60,
            expires_at: at + 3_600,
            revoked_at: None,
        },
        distribution,
        None,
        at,
    )?;
    Ok((trust, credentials, original_trust))
}

pub(super) fn ledger_at_with_original_trust(
    root: &std::path::Path,
